css:
[data-bz-section="utility-bar"] { background: var(--ink-dark); color: var(--hcm-on-navy); font-size: clamp(11px, 1.6vw, 13px); font-weight: 500; }
[data-bz-section="utility-bar"] .bz-row { align-items: center; row-gap: 8px; }
[data-bz-section="utility-bar"] .bz-block p { margin: 0; font-size: inherit; line-height: 1.15; }
[data-bz-node="utility-left"] { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 24px; }
[data-bz-node="utility-left"] > .bz-block { margin: 0; }
[data-bz-section="utility-bar"] .bz-menu { justify-content: flex-end; }
[data-bz-section="utility-bar"] .bz-nav { gap: 8px 24px; }
[data-bz-section="utility-bar"] .bz-navitem > a { font-family: var(--font-body); font-weight: 500; line-height: 1.15; font-size: inherit; padding: 0; color: var(--hcm-on-navy); }
[data-bz-section="utility-bar"] .bz-navitem > a:hover { color: #fff; }
[data-bz-section="utility-bar"] .bz-navitem > a[href^="tel:"] { color: #fff; font-weight: 700; }
@media (max-width: 640px) { [data-bz-section="utility-bar"] .bz-menu { justify-content: flex-start; } }
